  {highest : Matrix H Unit ℂ}
  {diagonal : ∀ (j : Fin d), generators.E j j = FreeEntropy.WeightSectors.weightDiagonal weight j}
  {highest_weight : ∀ (j : Fin d), generators.E j j * highest = row j • highest}
  {highest_raise : ∀ (i j : Fin d), i < j → generators.E i j * highest = 0} {cyclic : generators.cyclicSpan highest = ⊤}
  {dominant : ∀ (j : Fin (d - 1)), row (FreeEntropy.CasimirWeights.right j) ≤ row (FreeEntropy.CasimirWeights.left j)}
  {weightCoeff : H → Fin (d - 1) → ℕ}
  {weight_cone : ∀ (h : H), row - weight h = FreeEntropy.CasimirWeights.offset (weightCoeff h)}
  {generators_1 : FreeEntropy.LieMatrixCasimir.Generators d H} {row_1 : Fin d → ℝ} {weight_1 : H → Fin d → ℝ}
  {highest_1 : Matrix H Unit ℂ}
  {diagonal_1 : ∀ (j : Fin d), generators_1.E j j = FreeEntropy.WeightSectors.weightDiagonal weight_1 j}
  {highest_weight_1 : ∀ (j : Fin d), generators_1.E j j * highest_1 = row_1 j • highest_1}
  {highest_raise_1 : ∀ (i j : Fin d), i < j → generators_1.E i j * highest_1 = 0}
  {cyclic_1 : generators_1.cyclicSpan highest_1 = ⊤}
  {dominant_1 :
    ∀ (j : Fin (d - 1)), row_1 (FreeEntropy.CasimirWeights.right j) ≤ row_1 (FreeEntropy.CasimirWeights.left j)}
  {weightCoeff_1 : H → Fin (d - 1) → ℕ}
  {weight_cone_1 : ∀ (h : H), row_1 - weight_1 h = FreeEntropy.CasimirWeights.offset (weightCoeff_1 h)},
  { generators := generators, row := row, weight := weight, highest := highest, diagonal := diagonal,
        highest_weight := highest_weight, highest_raise := highest_raise, cyclic := cyclic, dominant := dominant,
        weightCoeff := weightCoeff, weight_cone := weight_cone } =
      { generators := generators_1, row := row_1, weight := weight_1, highest := highest_1, diagonal := diagonal_1,
        highest_weight := highest_weight_1, highest_raise := highest_raise_1, cyclic := cyclic_1,
        dominant := dominant_1, weightCoeff := weightCoeff_1, weight_cone := weight_cone_1 } →
    generators = generators_1 ∧ row = row_1 ∧ weight = weight_1 ∧ highest = highest_1 ∧ weightCoeff = weightCoeff_1

∀ {A : Type u_1} {B : Type u_2} {inst : Fintype A} {inst_1 : Fintype B} {inst_2 : DecidableEq A}
  {inst_3 : DecidableEq B} {d : ℕ} {M : FreeEntropy.CartanLieCloning.CyclicWeightModel d A}
  {N : FreeEntropy.CartanLieCloning.CyclicWeightModel d B} {κ : Type u_3} {inst_4 : Fintype κ} {inst_5 : DecidableEq κ}
  {T : κ → Type u_4} {inst_6 : (i : κ) → Fintype (T i)} {inst_7 : (i : κ) → DecidableEq (T i)}
  {constituent : (i : κ) → FreeEntropy.CartanLieCloning.CyclicWeightModel d (T i)}
  {embedding : (i : κ) → Matrix (A × B) (T i) ℂ} {isometry : ∀ (i : κ), (embedding i).conjTranspose * embedding i = 1}
  {resolution : ∑ i : κ, embedding i * (embedding i).conjTranspose = 1}
  {intertwines :
    ∀ (i : κ) (a b : Fin d),
      (M.generators.tensor N.generators).E a b * embedding i = embedding i * (constituent i).generators.E a b}
  {top : κ} {topWeight : (constituent top).row = M.row + N.row}
  {uniqueTop : ∀ (i : κ), (constituent i).row = M.row + N.row → i = top} {rootCoeff : κ → Fin (d - 1) → ℕ}
  {highestCone : ∀ (i : κ), M.row + N.row - (constituent i).row = FreeEntropy.CasimirWeights.offset (rootCoeff i)}
  {constituent_1 : (i : κ) → FreeEntropy.CartanLieCloning.CyclicWeightModel d (T i)}
  {embedding_1 : (i : κ) → Matrix (A × B) (T i) ℂ}
  {isometry_1 : ∀ (i : κ), (embedding_1 i).conjTranspose * embedding_1 i = 1}
  {resolution_1 : ∑ i : κ, embedding_1 i * (embedding_1 i).conjTranspose = 1}
  {intertwines_1 :
    ∀ (i : κ) (a b : Fin d),
      (M.generators.tensor N.generators).E a b * embedding_1 i = embedding_1 i * (constituent_1 i).generators.E a b}
  {top_1 : κ} {topWeight_1 : (constituent_1 top_1).row = M.row + N.row}
  {uniqueTop_1 : ∀ (i : κ), (constituent_1 i).row = M.row + N.row → i = top_1} {rootCoeff_1 : κ → Fin (d - 1) → ℕ}
  {highestCone_1 :
    ∀ (i : κ), M.row + N.row - (constituent_1 i).row = FreeEntropy.CasimirWeights.offset (rootCoeff_1 i)},
  { constituent := constituent, embedding := embedding, isometry := isometry, resolution := resolution,
        intertwines := intertwines, top := top, topWeight := topWeight, uniqueTop := uniqueTop, rootCoeff := rootCoeff,
        highestCone := highestCone } =
      { constituent := constituent_1, embedding := embedding_1, isometry := isometry_1, resolution := resolution_1,
        intertwines := intertwines_1, top := top_1, topWeight := topWeight_1, uniqueTop := uniqueTop_1,
        rootCoeff := rootCoeff_1, highestCone := highestCone_1 } →
    constituent = constituent_1 ∧ embedding = embedding_1 ∧ top = top_1 ∧ rootCoeff = rootCoeff_1

