  {Cμ : ι → Matrix H H ℂ} {Cν : ι → Matrix K K ℂ} {forward : FreeEntropy.Channels.MatrixChannel H K}
  {reverse : FreeEntropy.Channels.MatrixChannel K H} {positive_μ : ∀ i ∈ s, (Pμ i).PosSemidef}
  {positive_ν : ∀ i ∈ s, (Pν i).PosSemidef} {compressed_positive_ν : ∀ i ∈ s, (Cν i).PosSemidef}
  {trace_μ : ∀ i ∈ s, FreeEntropy.OrbitMemory.tr (Pμ i) = ↑(m i)}
  {trace_ν : ∀ i ∈ s, FreeEntropy.OrbitMemory.tr (Pν i) = ↑(n i)}
  {normalized_μ : (FreeEntropy.CloningMatrices.mixture s pμ Pμ).trace = 1}
  {normalized_ν : (FreeEntropy.CloningMatrices.mixture s pν Pν).trace = 1} {block_μ : ∀ i ∈ s, (1 - e i) • Pμ i ≤ Cμ i}
  {block_ν : ∀ i ∈ s, (1 - e i) • Pν i ≤ Cν i}
  {branch_forward :
    a • FreeEntropy.CloningMatrices.mixture s pμ Cν ≤ forward.toFun (FreeEntropy.CloningMatrices.mixture s pμ Pμ)}
  {branch_reverse :
    FreeEntropy.CloningMatrices.mixture s pν Cμ ≤ reverse.toFun (FreeEntropy.CloningMatrices.mixture s pν Pν)}
  {Pμ_1 : ι → Matrix H H ℂ} {Pν_1 : ι → Matrix K K ℂ} {Cμ_1 : ι → Matrix H H ℂ} {Cν_1 : ι → Matrix K K ℂ}
  {forward_1 : FreeEntropy.Channels.MatrixChannel H K} {reverse_1 : FreeEntropy.Channels.MatrixChannel K H}
  {positive_μ_1 : ∀ i ∈ s, (Pμ_1 i).PosSemidef} {positive_ν_1 : ∀ i ∈ s, (Pν_1 i).PosSemidef}
  {compressed_positive_ν_1 : ∀ i ∈ s, (Cν_1 i).PosSemidef}
  {trace_μ_1 : ∀ i ∈ s, FreeEntropy.OrbitMemory.tr (Pμ_1 i) = ↑(m i)}
  {trace_ν_1 : ∀ i ∈ s, FreeEntropy.OrbitMemory.tr (Pν_1 i) = ↑(n i)}
  {normalized_μ_1 : (FreeEntropy.CloningMatrices.mixture s pμ Pμ_1).trace = 1}
  {normalized_ν_1 : (FreeEntropy.CloningMatrices.mixture s pν Pν_1).trace = 1}
  {block_μ_1 : ∀ i ∈ s, (1 - e i) • Pμ_1 i ≤ Cμ_1 i} {block_ν_1 : ∀ i ∈ s, (1 - e i) • Pν_1 i ≤ Cν_1 i}
  {branch_forward_1 :
    a • FreeEntropy.CloningMatrices.mixture s pμ Cν_1 ≤ forward_1.toFun (FreeEntropy.CloningMatrices.mixture s pμ Pμ_1)}
  {branch_reverse_1 :
    FreeEntropy.CloningMatrices.mixture s pν Cμ_1 ≤ reverse_1.toFun (FreeEntropy.CloningMatrices.mixture s pν Pν_1)},
  { Pμ := Pμ, Pν := Pν, Cμ := Cμ, Cν := Cν, forward := forward, reverse := reverse, positive_μ := positive_μ,
        positive_ν := positive_ν, compressed_positive_ν := compressed_positive_ν, trace_μ := trace_μ,
        trace_ν := trace_ν, normalized_μ := normalized_μ, normalized_ν := normalized_ν, block_μ := block_μ,
        block_ν := block_ν, branch_forward := branch_forward, branch_reverse := branch_reverse } =
      { Pμ := Pμ_1, Pν := Pν_1, Cμ := Cμ_1, Cν := Cν_1, forward := forward_1, reverse := reverse_1,
        positive_μ := positive_μ_1, positive_ν := positive_ν_1, compressed_positive_ν := compressed_positive_ν_1,
        trace_μ := trace_μ_1, trace_ν := trace_ν_1, normalized_μ := normalized_μ_1, normalized_ν := normalized_ν_1,
        block_μ := block_μ_1, block_ν := block_ν_1, branch_forward := branch_forward_1,
        branch_reverse := branch_reverse_1 } →
